
import { mkdirSync, readFileSync, readdirSync, rmSync, statSync, writeFileSync } from "node:fs";
import { join, relative, sep } from "node:path";

const HERE = __dirname;
export const FILES_DIR = join(HERE, "files");
export const SHARED_SRC_DIR = join(HERE, "../../../../../../../packages/site-manifest/src");
export const SHARED_COPY_DIR = join(FILES_DIR, "src/zavi/manifest");
const OUT = join(HERE, "template-files.generated.ts");

export const COPY_BANNER =
  "// GENERATED COPY of packages/site-manifest/src (Zavi platform code). DO NOT EDIT:\n" +
  "// the Zavi deploy validates with the same code, and the next starter update overwrites this file.\n\n";

export function sharedCopies(): Array<{ name: string; content: string }> {
  return readdirSync(SHARED_SRC_DIR)
    .filter((n) => n.endsWith(".ts") && !n.endsWith(".test.ts"))
    .sort()
    .map((name) => ({ name, content: COPY_BANNER + readFileSync(join(SHARED_SRC_DIR, name), "utf-8") }));
}

export function syncSharedPackage(): number {
  rmSync(SHARED_COPY_DIR, { recursive: true, force: true });
  mkdirSync(SHARED_COPY_DIR, { recursive: true });
  const files = sharedCopies();
  for (const f of files) writeFileSync(join(SHARED_COPY_DIR, f.name), f.content, "utf-8");
  return files.length;
}

export function collectTemplateFiles(root: string = FILES_DIR): Array<{ path: string; content: string }> {
  const out: Array<{ path: string; content: string }> = [];
  const walk = (dir: string): void => {
    for (const name of readdirSync(dir).sort()) {
      const abs = join(dir, name);
      const st = statSync(abs);
      if (st.isDirectory()) walk(abs);
      else if (st.isFile()) out.push({ path: relative(root, abs).split(sep).join("/"), content: readFileSync(abs, "utf-8") });
    }
  };
  walk(root);
  return out;
}

export function renderModule(files: Array<{ path: string; content: string }>): string {
  const header = `// @generated by generate-template-files.ts — DO NOT EDIT BY HAND.
// Edit the source files under ./files/ (or packages/site-manifest/src) and re-run the
// generator. The drift test (__tests__/starter.test.ts) fails if this file is stale.
//
// Build-safe embedding of the vite-react-zavi site starter: a map of
// repo-relative path -> UTF-8 content, seeded into each new site repo.

export const TEMPLATE_FILES: Readonly<Record<string, string>> = Object.freeze({
`;
  const body = files.map(({ path, content }) => `  ${JSON.stringify(path)}: ${JSON.stringify(content)},`).join("\n");
  const footer = `
});

export const TEMPLATE_FILE_PATHS: readonly string[] = Object.freeze(Object.keys(TEMPLATE_FILES));
`;
  return header + body + footer;
}

export function writeGeneratedModule(): number {
  syncSharedPackage();
  const files = collectTemplateFiles();
  writeFileSync(OUT, renderModule(files), "utf-8");
  return files.length;
}

if (require.main === module) {
  const n = writeGeneratedModule();
  // eslint-disable-next-line no-console
  console.log(`wrote ${OUT} (${n} files)`);
}
